ift", "score": 1.212, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPA-067 (0.75)", "request matches RQC:RQC-032 (0.74); FAM:SF-APPA-067 auto_addresses_question RQC:RQC-032"], "attributes": {"observed_research_question": "TOV_FORCE 3-ply adversarial surviving lift", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Raw R1 TOV-force channel lifts survive opponent re-route or PT-shift (R2) and our follow-the-ball counter (R3).", "observed_result": "R1 lifts shrink ~50%+: ORL Banchero/Huerter +8.4 to net +3.7pp; DET Green/Anthony +7.0 to +3.5; PHI Harris/Vucevic +12.0 to +6.0; BOS Holiday/Council +6.1 to +2.8; PHX Booker/Wiggins +14.8 to +7.5; OKC Dort/Coffey +12.0  [cut; read_family for the full text]", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "Net lift is model-implied, not observed in the games; R3 often additive surrogate at n<10.", "observed_sample_and_power": "4 games; 8 offense-defense sides", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "descriptive"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPA-010"}, {"rel": "auto_measures", "node": "VAR:turnovers"}]}, {"id": "FAM:SF-APPS-058", "label": "Study family SF-APPS-058: Observed on-ball defensive scheme labels (ORL-DET G1)", "score": 1.08, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-058 (0.72)", "FAM:SF-APPA-001 auto_related_family (limitation_precedent) FAM:SF-APPS-058"], "attributes": {"observed_research_question": "Observed on-ball defensive scheme labels (ORL-DET G1)", "auto_outcome_status": "untestable", "observed_hypothesis": "NBA matchup/PBP fields can label on-ball coverage (DROP/ICE/SWITCH) at usable rates.", "observed_result": "DET: 67 on-ball HC poss, 10 labeled (14.9%) ? DROP n=5 PPP=1.20, ICE_CANDIDATE n=5 PPP=0.80, OTHER n=57 PPP=1.42. ORL: 60 poss, 2 labeled (3.3%). switches_on unpopulated.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Confident label rates 14.9% and 3.3%; NBA matchups feed did not populate switches_on.", "observed_sample_and_power": "n=67/60 possessions, 10/2 labeled", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "failed_gate"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPA-066", "label": "Study family SF-APPA-066: TOV_FORCE matchup decomposition on four playoff games", "score": 0.803, "reached_via": ["request matches RQC:RQC-031 (0.68); FAM:SF-APPA-066 auto_addresses_question RQC:RQC-031", "FAM:SF-APPA-067 auto_related_family (record_link_related_to) FAM:SF-APPA-066"], "attributes": {"observed_research_question": "TOV_FORCE matchup decomposition on four playoff games", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "TOV_FORCE as a top-3 lever can be decomposed into defender x initiator x PT channels with positive matchup lift.", "observed_result": "Team-PT lifts are small (ORL vs DET PNR +1.2pp; POR vs SAS all PT lifts negative, e.g. PNR -4.1pp) while player-channel lifts are large on small n (Banchero on Huerter SPOT_UP +8.4pp, n_def=17 / n_off=54; Dort on Coffey  [cut; read_family for the full text]", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Player-channel n often 15-28 defensive possessions; primary_defender attribution includes helper steals; no holdout or game-outcome check.", "observed_sample_and_power": "4 games; cell n often 15-54"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:insufficient_exposure"}, {"rel": "auto_has_risk", "node": "RISK:EXPOSURE_SPARSITY"}]}, {"id": "FAM:SF-APPA-004", "label": "Study family SF-APPA-004: DID-ADAPT case study NYK vs PHI 2025-26 series", "score": 0.566, "reached_via": ["FAM:SF13 auto_related_family (record_link_related_to) FAM:SF-APPA-004", "request matches VAR:three_point_attempts_or_luck (0.66); FAM:SF-APPA-004 auto_measures VAR:three_point_attempts_or_luck"], "attributes": {"observed_research_question": "DID-ADAPT case study NYK vs PHI 2025-26 series", "auto_outcome_status": "untestable", "observed_hypothesis": "Within-game and within-series adaptation toward engine counters coincides with better PPP in one series.", "observed_result": "Adapters 4/8 rows; mean dPPP adapters +0.0327 vs non-adapters -0.2987. A2 could not be computed: no SHOULD vector in correction_log.json.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "n=8 team-game rows; series SHOULD vector missing.", "observed_sample_and_power": "n=8", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "inconclusive", "observed_failure_type": "A_unanswerable"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:selection_or_regression_to_the_mean"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}, {"rel": "auto_related_family", "node": "FAM:SF-APPM-020"}, {"rel": "auto_related_family", "node": "FAM:SF13"}]}, {"id": "FAM:SF-APPS-012", "label": "Study family SF-APPS-012: Defensive PPP allowed and possession share, RS vs playoffs", "score": 0.443, "reached_via": ["request matches RQC:RQC-049 (0.70); FAM:SF-APPS-012 auto_addresses_question RQC:RQC-049"], "attributes": {"observed_research_question": "Defensive PPP allowed and possession share, RS vs playoffs", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Playoff defenses suppress DRIVE more than RS defenses (both lower PPP allowed and lower share).", "observed_result": "DRIVE allowed 1.191 -> 0.923 (-0.268), share 21.2% -> 18.2%; PNR -0.139, share +12.1pp; PULL_UP +0.341, share -7.6pp.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No inferential test; PNR share jump of +12.1pp may reflect tagging differences.", "observed_sample_and_power": "25 teams", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "25 defensive teams, min 30 poss per cell; RS vs playoff PPP allowed and opponent possession share by PT.", "observed_verdict": "descriptive", "observed_failure_type": "E_unclear"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}]}, {"id": "FAM:SF-APPM-022", "label": "Study family SF-APPM-022: Superstar suppression profiles (incl. Q5c sequential triggering)", "score": 0.441, "reached_via": ["request matches RQC:RQC-040 (0.70); FAM:SF-APPM-022 auto_addresses_question RQC:RQC-040"], "attributes": {"observed_research_question": "Superstar suppression profiles (incl. Q5c sequential triggering)", "auto_outcome_status": "inconclusive", "observed_hypothesis": "Specific opposing lineups, defenders, play types and preceding opponent play types suppress star efficiency.", "observed_result": "Q5c verdict 'rank-1 suppressor varies meaningfully across players'; e.g. Jokic after opp POST_UP 1.1271 (-0.0675, SE +/-0.0500, n=480); Curry forced POST_UP -0.209.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "Rank-1 deltas mostly within 1-2 SE with no multiple-comparison control; OTHER artifact flagged in doc.", "observed_sample_and_power": "SE per cell reported", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Initiator possessions for 4 then ~30 stars (gate >=15); Q5c ranks opponent prior-PT by target PPP for 14 players; reruns 2026-05-06 and 2026-05-30."}, "relationships": []}, {"id": "FAM:SF-CHT-009", "label": "Study family SF-CHT-009: Superstar suppression by lineup and forced play type", "score": 0.434, "reached_via": ["request matches RQC:RQC-055 (0.69); FAM:SF-CHT-009 auto_addresses_question RQC:RQC-055"], "attributes": {"observed_research_question": "Superstar suppression by lineup and forced play type", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Named star initiators have identifiable lineup and forced-play-type suppressors in the possession graph.", "observed_result": "Jokic vs MIN lineup PPP 0.814, -0.385 (n=59); Curry vs HOU 0.851, -0.358 (n=47); Doncic vs LAC 0.733, -0.396 (n=30); Giannis forced PULL_UP 0.848, -0.540 vs preferred DRIVE (largest gap).", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No placebo or matching; later sequence work treated similar star-chain gaps as artifacts.", "observed_sample_and_power": "n>=30 for lineup cells cited", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Jokic/Curry/Doncic/Giannis; min-15 gate on 8 play types; opposing DEFENSE_LINEUP ~84% coverage; 272-row CSV."}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:PLACEBO_DEPENDENCE"}]}], "n_results": 10}

